CREATE DATABASE IF NOT EXISTS brandalbet CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE brandalbet;
CREATE TABLE users(id CHAR(36) PRIMARY KEY,username VARCHAR(64) NOT NULL UNIQUE,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('member','operator','finance','admin','superadmin') NOT NULL DEFAULT 'member',status ENUM('active','suspended','blocked','pending') NOT NULL DEFAULT 'active',display_name VARCHAR(120),phone VARCHAR(40),referral_code VARCHAR(32) UNIQUE,referred_by VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,last_login_at TIMESTAMP NULL) ENGINE=InnoDB;
CREATE TABLE user_sessions(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,token_hash CHAR(64) NOT NULL UNIQUE,device_id VARCHAR(190),session_type ENUM('member','backoffice') NOT NULL DEFAULT 'member',ip VARCHAR(64),user_agent VARCHAR(500),expires_at TIMESTAMP NOT NULL,revoked_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(expires_at),CONSTRAINT fk_session_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE member_profiles(user_id CHAR(36) PRIMARY KEY,display_name VARCHAR(120),phone VARCHAR(40),avatar_url TEXT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_profile_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE bank_accounts(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,type VARCHAR(20) NOT NULL,provider VARCHAR(80) NOT NULL,account_number VARCHAR(120) NOT NULL,account_name VARCHAR(160) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),CONSTRAINT fk_bank_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE wallets(user_id CHAR(36) PRIMARY KEY,balance DECIMAL(20,2) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_wallet_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE wallet_ledger(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,transaction_id CHAR(36),direction ENUM('credit','debit') NOT NULL,amount DECIMAL(20,2) NOT NULL,balance_before DECIMAL(20,2) NOT NULL,balance_after DECIMAL(20,2) NOT NULL,reason VARCHAR(120) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),CONSTRAINT fk_ledger_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE transactions(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,type VARCHAR(40) NOT NULL,amount DECIMAL(20,2) NOT NULL,status VARCHAR(30) NOT NULL,reference VARCHAR(190) UNIQUE,metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at),CONSTRAINT fk_tx_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE deposits(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,amount DECIMAL(20,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',gateway VARCHAR(80),gateway_reference VARCHAR(190) UNIQUE,expires_at TIMESTAMP NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,status),CONSTRAINT fk_dep_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE withdrawals(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,amount DECIMAL(20,2) NOT NULL,status VARCHAR(30) NOT NULL DEFAULT 'pending',bank_account_id CHAR(36),gateway_reference VARCHAR(190) UNIQUE,reject_reason VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,status),CONSTRAINT fk_wd_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE cashback_accounts(user_id CHAR(36) PRIMARY KEY,balance DECIMAL(20,2) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,CONSTRAINT fk_cash_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE cashback_transactions(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,amount DECIMAL(20,2) NOT NULL,type VARCHAR(40) NOT NULL,status VARCHAR(30) NOT NULL,reference VARCHAR(190) UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,created_at)) ENGINE=InnoDB;
CREATE TABLE referrals(id CHAR(36) PRIMARY KEY,referrer_id CHAR(36) NOT NULL,referred_id CHAR(36) NOT NULL UNIQUE,code VARCHAR(32),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE providers(id CHAR(36) PRIMARY KEY,code VARCHAR(64) NOT NULL UNIQUE,name VARCHAR(120) NOT NULL,is_active BOOLEAN NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,config_json JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE games(id CHAR(36) PRIMARY KEY,provider_code VARCHAR(64) NOT NULL,game_code VARCHAR(120) NOT NULL,name VARCHAR(190) NOT NULL,category VARCHAR(80),image_url TEXT,is_active BOOLEAN NOT NULL DEFAULT 1,is_popular BOOLEAN NOT NULL DEFAULT 0,is_new BOOLEAN NOT NULL DEFAULT 0,sort_order INT NOT NULL DEFAULT 0,UNIQUE KEY uq_game(provider_code,game_code),INDEX(provider_code,is_active,sort_order)) ENGINE=InnoDB;
CREATE TABLE game_launches(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,game_id CHAR(36) NOT NULL,provider VARCHAR(64) NOT NULL,request_id VARCHAR(190) UNIQUE,provider_reference VARCHAR(190),status VARCHAR(30) NOT NULL,launch_url TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE promotions(id CHAR(36) PRIMARY KEY,title VARCHAR(190) NOT NULL,description TEXT,image_url TEXT,start_at TIMESTAMP NULL,end_at TIMESTAMP NULL,is_active BOOLEAN NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE payment_connections(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL,provider VARCHAR(80) NOT NULL,mode VARCHAR(20) NOT NULL,encrypted_config TEXT NOT NULL,is_active BOOLEAN NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE audit_logs(id CHAR(36) PRIMARY KEY,actor_user_id CHAR(36),action VARCHAR(120) NOT NULL,target_type VARCHAR(80),target_id VARCHAR(190),ip VARCHAR(64),metadata JSON,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),INDEX(actor_user_id)) ENGINE=InnoDB;